changeSet.sql:

if not exists (select * from INFORMATION_SCHEMA.COLUMNS where TABLE_SCHEMA = 'metrics' and TABLE_NAME = 'Asset' and COLUMN_NAME = 'AllocationUid')
begin
	alter table metrics.Asset add AllocationUid uniqueidentifier null;
end
GO

if exists (select * from INFORMATION_SCHEMA.COLUMNS where TABLE_SCHEMA = 'metrics' and TABLE_NAME = 'Asset' and COLUMN_NAME = 'AssetTypeUid')
begin
	update	T
	set		T.AllocationUid = S.Uid
	from	metrics.Asset T
			inner join metrics.Allocation S on S.AssetTypeUid = T.AssetTypeUid and S.ScoreType = T.ScoreType;

	alter table metrics.Asset alter column AllocationUid uniqueidentifier not null;

	ALTER TABLE [metrics].[Asset]  WITH CHECK ADD  CONSTRAINT [FK_MetricAsset_MetricAllocation] FOREIGN KEY([AllocationUid]) REFERENCES [metrics].[Allocation] ([Uid]) ON DELETE CASCADE
	ALTER TABLE [metrics].[Asset] CHECK CONSTRAINT [FK_MetricAsset_MetricAllocation]
end
GO

if exists (select * from INFORMATION_SCHEMA.COLUMNS where TABLE_SCHEMA = 'metrics' and TABLE_NAME = 'Asset' and COLUMN_NAME = 'AssetTypeUid')
begin
	alter table metrics.Asset drop column AssetTypeUid;
	alter table metrics.Asset drop column ScoreType;
end

changeSet.rollback:

if exists (select * from INFORMATION_SCHEMA.COLUMNS where TABLE_SCHEMA = 'metrics' and TABLE_NAME = 'Asset' and COLUMN_NAME = 'AllocationUid')
begin
	alter table metrics.Asset add AssetTypeUid uniqueidentifier null;
	alter table metrics.Asset add ScoreType int null;
end
GO

if exists (select * from INFORMATION_SCHEMA.COLUMNS where TABLE_SCHEMA = 'metrics' and TABLE_NAME = 'Asset' and COLUMN_NAME = 'AllocationUid')
begin
	update	T
	set		T.AssetTypeUid = S.AssetTypeUid,
			T.ScoreType = S.ScoreType
	from	metrics.Asset T
			inner join metrics.Allocation S on S.Uid = T.AllocationUid;


	ALTER TABLE [metrics].[Asset] DROP CONSTRAINT [FK_MetricAsset_MetricAllocation];
	alter table metrics.Asset drop column AllocationUid;
end
